SELECT Name, Country, Age
FROM singer
ORDER BY Age DESC;

SELECT Name, Country, Age
FROM singer
ORDER BY Age DESC;

SELECT Song_Name, Song_release_year
FROM singer
WHERE Age = (SELECT MIN(Age) FROM singer);

SELECT Location, Name
FROM stadium
WHERE Capacity BETWEEN 5000 AND 10000;

SELECT PetID, weight
FROM Pets
WHERE pet_age > 1;

SELECT StuID, COUNT(*) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT cm.Maker, ml.Model
FROM car_makers AS cm
JOIN model_list AS ml ON ml.Maker = cm.Id;

SELECT DISTINCT Year
FROM cars_data
WHERE Weight BETWEEN 3000 AND 4000;

SELECT DISTINCT Year
FROM cars_data
WHERE Year IN (
    SELECT Year FROM cars_data WHERE Weight < 4000
) AND Year IN (
    SELECT Year FROM cars_data WHERE Weight > 3000
);

SELECT Airline, Abbreviation
FROM airlines
WHERE Country = 'USA';

SELECT AirportCode, AirportName
FROM airports
WHERE City = 'Anthony';

SELECT AirportCode, AirportName
FROM airports
WHERE City = 'Anthony';

SELECT City, Country
FROM airports
WHERE AirportName LIKE '%Alton%';

SELECT Location, COUNT(*) AS shop_count
FROM shop
GROUP BY Location;

SELECT Name
FROM shop
WHERE Number_products > (SELECT AVG(Number_products) FROM shop);

SELECT Document_ID, Template_ID, Document_Description
FROM Documents
WHERE Document_Name = 'Robbin CV';

SELECT Version_Number, Template_Type_Code
FROM Templates
WHERE Version_Number > 5;

SELECT first_name, country_code
FROM players
WHERE birth_date = (SELECT MIN(birth_date) FROM players);

SELECT first_name || ' ' || last_name AS full_name
FROM players
ORDER BY birth_date;

SELECT hand, COUNT(*) AS player_count
FROM players
GROUP BY hand;

SELECT name, result
FROM battle
WHERE bulgarian_commander <> 'Boril';

SELECT DISTINCT c.course_name
FROM Courses c
JOIN Student_Enrolment_Courses sec ON c.course_id = sec.course_id;

SELECT other_student_details
FROM Students
ORDER BY last_name DESC;

SELECT Title, Directed_by
FROM Cartoon
ORDER BY Original_air_date;

SELECT Title
FROM Cartoon
WHERE Directed_by IN ('Ben Jones', 'Brandon Vietti');

SELECT Language, COUNT(*) AS channel_count
FROM TV_Channel
GROUP BY Language;

SELECT Episode
FROM TV_series
ORDER BY CAST(Rating AS REAL) DESC;

SELECT Directed_by, COUNT(*) AS cartoon_count
FROM Cartoon
GROUP BY Directed_by;

SELECT Directed_by, COUNT(*) AS cartoon_count
FROM Cartoon
GROUP BY Directed_by;

SELECT Package_Option, series_name
FROM TV_Channel
WHERE Hight_definition_TV = 'yes';

SELECT Package_Option, series_name
FROM TV_Channel
WHERE Hight_definition_TV = 'yes';

SELECT MAX(created) AS last_date_created
FROM VOTES
WHERE state = 'CA';

SELECT Continent
FROM country
WHERE Name = 'Anguilla';

SELECT Population, LifeExpectancy
FROM country
WHERE Name = 'Brazil';

SELECT AVG(LifeExpectancy) AS avg_life_expectancy
FROM country
WHERE Region = 'Central Africa';

SELECT COUNT(DISTINCT GovernmentForm) AS government_types
FROM country
WHERE Continent = 'Africa';

SELECT COUNT(*) 
FROM countrylanguage 
WHERE CountryCode = 'AFG' AND IsOfficial = 'T';

SELECT COUNT(*) 
FROM countrylanguage 
WHERE CountryCode = 'AFG' AND IsOfficial = 'T';

SELECT CountryCode
FROM countrylanguage
WHERE Language = 'Spanish' AND Percentage = (
    SELECT MAX(Percentage) FROM countrylanguage WHERE Language = 'Spanish'
);

SELECT Name
FROM conductor
ORDER BY Age ASC;

SELECT Record_Company
FROM orchestra
ORDER BY Year_of_Founded DESC;

SELECT COUNT(*) 
FROM Friend 
WHERE student_id = (SELECT ID FROM Highschooler WHERE name = 'Kyle');

SELECT h.ID
FROM Highschooler h
WHERE NOT EXISTS (
    SELECT 1 FROM Friend f WHERE f.student_id = h.ID OR f.friend_id = h.ID
);

SELECT h.name
FROM Highschooler h
WHERE EXISTS (
    SELECT 1 FROM Friend f
    WHERE f.student_id = h.ID OR f.friend_id = h.ID
)
AND EXISTS (
    SELECT 1 FROM Likes l
    WHERE l.liked_id = h.ID
);

SELECT liked_id AS student_id, COUNT(*) AS like_count
FROM Likes
GROUP BY liked_id;

SELECT COUNT(*) 
FROM Likes 
WHERE liked_id = (SELECT ID FROM Highschooler WHERE name = 'Kyle');

SELECT COUNT(*) 
FROM Dogs 
WHERE CAST(age AS REAL) < (SELECT AVG(CAST(age AS REAL)) FROM Dogs);

SELECT Citizenship, MAX(Net_Worth_Millions) AS Max_Net_Worth
FROM singer
GROUP BY Citizenship;

SELECT Name
FROM singer
WHERE Singer_ID NOT IN (SELECT Singer_ID FROM song);
